import re

def safety_response(text: str):
    s = text.lower().replace('ё','е')
    if re.search(r'(убить себя|покончить с собой|суицид|самоубий|не хочу жить|хочу умереть|причинить себе вред|вскрыть вены|прыгну с|передозиров|убью себя|убить человека|убью его)', s):
        return {'kind':'crisis','content':'Мне жаль, что сейчас так тяжело. Если есть непосредственная опасность, позвони 112 или обратись в ближайшее отделение экстренной помощи. По возможности отойди от того, чем можно навредить себе, и свяжись с человеком, который сможет побыть рядом. MINDPRINT AI не является службой экстренной помощи. Психолог не получает автоматического экстренного уведомления.'}
    if re.search(r'(дозиров|доз[ауые] |таблет|препарат|антидепресс|поставь диагноз|какой.*диагноз|у меня.*расстройств)', s):
        return {'kind':'medical','content':'Я не могу ставить диагнозы или рекомендовать препараты и их дозировку. Обсуди этот вопрос с лечащим врачом. Могу помочь сформулировать вопросы для встречи.'}
    return None
